class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff315d35)),useMaterial3:true),home:const Wheel());}
class Wheel extends StatefulWidget{const Wheel({super.key});@override State<Wheel> createState()=>_WheelState();}
class _WheelState extends State<Wheel>{int step=1;bool ended=false,showExcluded=false;final answers=<int,String>{};final route=<String>[];DeterminationResult get result=>determine(answers);void choose(WheelOption o)=>setState((){answers[step]=o.label;route.add('$step. ${o.label}');ended=o.end;if(o.next!=null)step=o.next!;});void reset()=>setState((){step=1;ended=false;showExcluded=false;answers.clear();route.clear();});@override Widget build(BuildContext context){final current=wheelSteps[step]!;return Scaffold(appBar:AppBar(title:const Text('Paddenstoelen Determinatiewiel'),actions:[IconButton(onPressed:reset,icon:const Icon(Icons.restart_alt))]),body:SafeArea(child:LayoutBuilder(builder:(context,b)=>Padding(padding:const EdgeInsets.all(16),child:b.maxWidth>850?Row(children:[Expanded(flex:6,child:_wheel(current)),const SizedBox(width:20),Expanded(flex:5,child:_panel(current))]):Column(children:[Expanded(flex:5,child:_wheel(current)),Expanded(flex:6,child:_panel(current))])))));}
Widget _wheel(WheelStep current)=>Center(child:AspectRatio(aspectRatio:1,child:Stack(alignment:Alignment.center,children:[CustomPaint(size:Size.infinite,painter:_WheelPainter(route.length,ended)),FractionallySizedBox(widthFactor:.52,heightFactor:.52,child:Card(elevation:8,shape:const CircleBorder(),child:Padding(padding:const EdgeInsets.all(22),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('Observatie ${route.length+1}',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text(current.title,textAlign:TextAlign.center,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(current.help,textAlign:TextAlign.center)]))))])));
Widget _panel(WheelStep current){final r=result;return Card(child:Padding(padding:const EdgeInsets.all(18),child:ListView(children:[Text(ended?'Determinatie-overzicht':'Observatie ${route.length+1} — ${current.title}',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:10),if(answers[4]=='Plaatjes')...[_candidatePanel(r),const Divider(height:20)],if(ended)_resultPanel(r)else...current.options.map(_optionCard),if(route.isNotEmpty)...[const Divider(height:28),const Text('Gevolgde route',style:TextStyle(fontWeight:FontWeight.bold)),Text(route.join('  →  '))]])));}
Widget _candidatePanel(DeterminationResult r)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text('Kandidaatgroepen: ${r.remaining.length}',style:const TextStyle(fontWeight:FontWeight.bold))),TextButton.icon(onPressed:()=>setState(()=>showExcluded=!showExcluded),icon:Icon(showExcluded?Icons.expand_less:Icons.expand_more),label:Text('${r.excluded.length} uitgesloten'))]),Wrap(spacing:6,runSpacing:4,children:r.remaining.map((x)=>Chip(label:Text(x.name))).toList()),if(showExcluded)...r.excluded.entries.map((e)=>ListTile(dense:true,leading:const Icon(Icons.block,size:18),title:Text(e.key.name),subtitle:Text(e.value)))]);
Widget _resultPanel(DeterminationResult r){final key=detailKeyFor(genusHint:r.genusHint,candidateNames:r.remaining.map((x)=>x.name));return Column(children:[const Icon(Icons.fact_check_outlined,size:48),if(r.genusHint!=null)ListTile(leading:const Icon(Icons.call_split),title:Text('Bronondersteunde geslachtssplitsing: ${r.genusHint}')),if(answers[4]=='Plaatjes')...r.remaining.map((x)=>ListTile(leading:const Icon(Icons.eco_outlined),title:Text(x.name))),if(key!=null)Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(children:[Text(key.title,style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:6),Text(key.sourceNote,textAlign:TextAlign.center),const SizedBox(height:10),FilledButton.icon(onPressed:()=>_openDetailKey(key),icon:const Icon(Icons.account_tree_outlined),label:const Text('Open detailsleutel'))]))else const Text('Voor deze kandidaat bevat de huidige bronset nog geen eenduidige gecodeerde detailsleutel. Vul geen soortnaam in op basis van aannames.',textAlign:TextAlign.center),const SizedBox(height:12),const Text('Een soortnaam wordt pas getoond wanneer een echte detailsleutel voldoende uitsluitende kenmerken levert.',textAlign:TextAlign.center),const SizedBox(height:12),Card(color:Theme.of(context).colorScheme.errorContainer,child:const Padding(padding:EdgeInsets.all(12),child:Text('Niet gebruiken als bewijs van eetbaarheid. Bevestig een determinatie onafhankelijk.'))),FilledButton.icon(onPressed:reset,icon:const Icon(Icons.restart_alt),label:const Text('Nieuwe determinatie'))]);}
void _openDetailKey(DetailKey key){String? initial;if(key.id=='russulaceae')initial=answers[22];if(key.id=='galerina')initial=answers[17];Navigator.of(context).push(MaterialPageRoute(builder:(_)=>DetailKeyPage(keyData:key,initialAnswer:initial)));}
Widget _optionCard(WheelOption o)=>Padding(padding:const EdgeInsets.only(bottom:10),child:InkWell(borderRadius:BorderRadius.circular(16),onTap:()=>choose(o),child:Container(padding:const EdgeInsets.all(10),decoration:BoxDecoration(color:Theme.of(context).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(16)),child:Row(children:[DiagnosticIllustration(art:artFor(o.label),size:78),const SizedBox(width:14),Expanded(child:Text(o.label,style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w600))),const Icon(Icons.chevron_right)]))));}
}
class DetailKeyPage extends StatefulWidget{const DetailKeyPage({super.key,required this.keyData,this.initialAnswer});final DetailKey keyData;final String? initialAnswer;@override State<DetailKeyPage> createState()=>_DetailKeyPageState();}
class _DetailKeyPageState extends State<DetailKeyPage>{late String stepId;String? result;SourceTaxonCatalog? get catalog=>sourceCatalogs[widget.keyData.id];@override void initState(){super.initState();stepId=widget.keyData.start;if(widget.initialAnswer!=null){final step=widget.keyData.steps[stepId]!;for(final o in step.options){if(o.label==widget.initialAnswer&&o.result!=null)result=o.result;}}}void pick(DetailOption o)=>setState((){if(o.result!=null)result=o.result;if(o.next!=null)stepId=o.next!;});@override Widget build(BuildContext context){final step=widget.keyData.steps[stepId]!,cat=catalog;return Scaffold(appBar:AppBar(title:Text(widget.keyData.title)),body:ListView(padding:const EdgeInsets.all(20),children:[Text(widget.keyData.sourceNote,style:Theme.of(context).textTheme.bodySmall),if(cat!=null)...[const SizedBox(height:12),Card(child:ExpansionTile(initiallyExpanded:true,title:Text('Bronprofiel — ${cat.group}'),children:[for(final p in cat.profile)ListTile(dense:true,leading:const Icon(Icons.check_circle_outline,size:18),title:Text(p)),if(cat.taxa.isNotEmpty)...[const Divider(),const ListTile(title:Text('Soorten genoemd in de aangeleverde bron',style:TextStyle(fontWeight:FontWeight.bold))),Padding(padding:const EdgeInsets.fromLTRB(16,0,16,12),child:Wrap(spacing:6,runSpacing:6,children:[for(final taxon in cat.taxa)Chip(label:Text(taxon))]))],Padding(padding:const EdgeInsets.all(12),child:Text(cat.note,style:Theme.of(context).textTheme.bodySmall))]))],const SizedBox(height:20),if(result==null)...[Text(step.title,style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(step.help),const SizedBox(height:16),...step.options.map((o)=>Card(child:ListTile(leading:DiagnosticIllustration(art:artFor(o.label),size:58),title:Text(o.label),trailing:const Icon(Icons.chevron_right),onTap:()=>pick(o)))],if(result!=null)...[const Icon(Icons.account_tree_outlined,size:64),const SizedBox(height:12),Text(result!,textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),const Text('Dit is het diepste niveau dat de momenteel gecodeerde broncriteria ondersteunen. De hierboven genoemde soorten zijn referenties uit de bron en worden niet automatisch als uitkomst gekozen zonder onderscheidende sleutelkenmerken.',textAlign:TextAlign.center),const SizedBox(height:20),OutlinedButton(onPressed:()=>setState(()=>result=null),child:const Text('Waarneming opnieuw beoordelen'))]]));}}
class _WheelPainter extends CustomPainter{
  _WheelPainter(this.completed,this.ended);
  final int completed;
  final bool ended;
  @override void paint(Canvas c,Size z){
    final center=Offset(z.width/2,z.height/2),radius=z.shortestSide*.48;
    final base=Paint()..style=PaintingStyle.stroke..strokeWidth=z.shortestSide*.11..strokeCap=StrokeCap.round..color=const Color(0xffdde8d7);
    c.drawCircle(center,radius*.86,base);
    if(completed>0||ended){
      // The source uses numbered sections/groups, not a fixed 24-step decision
      // sequence. Show path progress without implying those section numbers are
      // sequential determination steps.
      final fraction=ended?1.0:(completed/(completed+4)).clamp(0.0,.92);
      final progress=Paint()..style=PaintingStyle.stroke..strokeWidth=z.shortestSide*.11..strokeCap=StrokeCap.round..color=const Color(0xff315d35);
      c.drawArc(Rect.fromCircle(center:center,radius:radius*.86),-math.pi/2,2*math.pi*fraction,false,progress);
    }
    final tp=TextPainter(textDirection:TextDirection.ltr,textAlign:TextAlign.center);
    tp.text=TextSpan(text:ended?'controle':completed==0?'start':'$completed\nwaarnemingen',style:TextStyle(fontSize:z.shortestSide*.035,fontWeight:FontWeight.w700,color:const Color(0xff315d35)));
    tp.layout();
    tp.paint(c,center-Offset(tp.width/2,tp.height/2));
  }
  @override bool shouldRepaint(covariant _WheelPainter old)=>old.completed!=completed||old.ended!=ended;
}
